/**
 * Placeholder login emails (company-name@finderb.com) are generated by the
 * admin console when a merchant is onboarded without a real email address.
 * They are valid login credentials but must never be displayed as the
 * merchant's contact email — those profiles are treated as "email missing"
 * until the merchant saves a real address.
 */
export const PLACEHOLDER_EMAIL_DOMAIN = 'finderb.com';

export function isPlaceholderEmail(email: string | null | undefined): boolean {
  return Boolean(
    email && email.trim().toLowerCase().endsWith(`@${PLACEHOLDER_EMAIL_DOMAIN}`),
  );
}

/** First usable public email, skipping placeholders. Undefined = missing. */
export function pickPublicBusinessEmail(
  ...candidates: (string | null | undefined)[]
): string | undefined {
  for (const candidate of candidates) {
    const value = typeof candidate === 'string' ? candidate.trim() : '';
    if (value && !isPlaceholderEmail(value)) return value;
  }
  return undefined;
}
